int knapsack(vector<int>& wt, vector<int>& val, int W) {
    vector<int> dp(W + 1, 0);
    for (int i = 0; i < (int)wt.size(); ++i)
        for (int w = W; w >= wt[i]; --w)        // high -> low for 0/1
            dp[w] = max(dp[w], dp[w - wt[i]] + val[i]);
    return dp[W];
}

def knapsack(wt, val, W):
    dp = [0] * (W + 1)
    for i in range(len(wt)):
        for w in range(W, wt[i] - 1, -1):      # high -> low for 0/1
            dp[w] = max(dp[w], dp[w - wt[i]] + val[i])
    return dp[W]

class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total & 1) return false;
        int target = total / 2;
        vector<bool> dp(target + 1, false); dp[0] = true;
        for (int x : nums)
            for (int s = target; s >= x; s--)
                dp[s] = dp[s] || dp[s - x];
        return dp[target];
    }
};

class Solution:
    def canPartition(self, nums: list[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        dp = [False] * (target + 1)
        dp[0] = True
        for x in nums:
            for s in range(target, x - 1, -1):
                dp[s] = dp[s] or dp[s - x]
        return dp[target]

class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int S) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (abs(S) > total || ((total + S) & 1)) return 0;
        int target = (total + S) / 2;
        vector<int> dp(target + 1, 0); dp[0] = 1;
        for (int x : nums)
            for (int s = target; s >= x; s--)
                dp[s] += dp[s - x];
        return dp[target];
    }
};

class Solution:
    def findTargetSumWays(self, nums: list[int], S: int) -> int:
        total = sum(nums)
        if abs(S) > total or (total + S) % 2:
            return 0
        target = (total + S) // 2
        dp = [1] + [0] * target
        for x in nums:
            for s in range(target, x - 1, -1):
                dp[s] += dp[s - x]
        return dp[target]

class Solution {
public:
    int lastStoneWeightII(vector<int>& stones) {
        int total = accumulate(stones.begin(), stones.end(), 0);
        int half = total / 2;
        vector<bool> dp(half + 1, false); dp[0] = true;
        int best = 0;
        for (int x : stones)
            for (int s = half; s >= x; s--)
                if (dp[s - x]) { dp[s] = true; best = max(best, s); }
        return total - 2 * best;
    }
};

class Solution:
    def lastStoneWeightII(self, stones: list[int]) -> int:
        total = sum(stones)
        half = total // 2
        dp = [False] * (half + 1)
        dp[0] = True
        best = 0
        for x in stones:
            for s in range(half, x - 1, -1):
                if dp[s - x]:
                    dp[s] = True
                    best = max(best, s)
        return total - 2 * best

class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, amount + 1); dp[0] = 0;
        for (int c : coins)
            for (int a = c; a <= amount; a++)
                dp[a] = min(dp[a], dp[a - c] + 1);
        return dp[amount] > amount ? -1 : dp[amount];
    }
};

class Solution:
    def coinChange(self, coins: list[int], amount: int) -> int:
        dp = [amount + 1] * (amount + 1)
        dp[0] = 0
        for c in coins:
            for a in range(c, amount + 1):
                dp[a] = min(dp[a], dp[a - c] + 1)
        return -1 if dp[amount] > amount else dp[amount]

class Solution {
public:
    int profitableSchemes(int n, int minProfit, vector<int>& group, vector<int>& profit) {
        const long long MOD = 1e9 + 7;
        vector<vector<long long>> dp(n + 1, vector<long long>(minProfit + 1, 0));
        for (int g = 0; g <= n; g++) dp[g][0] = 1;
        for (int i = 0; i < (int)group.size(); i++) {
            int g = group[i], p = profit[i];
            for (int used = n; used >= g; used--)
                for (int pr = minProfit; pr >= 0; pr--)
                    dp[used][pr] = (dp[used][pr] + dp[used - g][max(0, pr - p)]) % MOD;
        }
        return (int)dp[n][minProfit];
    }
};

class Solution:
    def profitableSchemes(self, n, minProfit, group, profit):
        MOD = 10**9 + 7
        dp = [[0] * (minProfit + 1) for _ in range(n + 1)]
        for g in range(n + 1):
            dp[g][0] = 1
        for g, p in zip(group, profit):
            for used in range(n, g - 1, -1):
                for pr in range(minProfit, -1, -1):
                    dp[used][pr] = (dp[used][pr] + dp[used - g][max(0, pr - p)]) % MOD
        return dp[n][minProfit]
